    private final Map<UUID, Agreement> agreements = new LinkedHashMap<>();
    private final Map<UUID, Double> debts = new LinkedHashMap<>();
    private final List<LedgerEntry> ledger = new ArrayList<>();
    private double serverBank; private boolean dirty; private boolean economyPaused;private int economyStorageVersion=1;
    public boolean healthy(){try(var guard=ru.neverland.core.SuiteState.guard()){return ready&&ru.neverland.core.AtomicFiles.writable(file.toPath());}}
    public boolean usesPaymentsDb(){try(var guard=ru.neverland.core.SuiteState.guard()){gate();return economyStorageVersion==2;}}
